def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = set()
    history = []
    rejected = []

    arity = {
        "open": 3,
        "deposit": 3,
        "withdraw": 3,
        "transfer": 4,
        "freeze": 2,
        "unfreeze": 2,
        "undo": 1,
    }

    def remember(names):
        history.append([
            (name, balances.get(name), name in frozen)
            for name in names
        ])

    for index, operation in enumerate(ops):
        tokens = operation.split(" ")
        verb = tokens[0]

        if (
            verb not in arity
            or len(tokens) != arity[verb]
            or any(token == "" for token in tokens)
        ):
            rejected.append(index)
            continue

        if verb == "undo":
            if not history:
                rejected.append(index)
                continue

            for name, old_balance, was_frozen in history.pop():
                if old_balance is None:
                    balances.pop(name, None)
                else:
                    balances[name] = old_balance

                if was_frozen:
                    frozen.add(name)
                else:
                    frozen.discard(name)
            continue

        name = tokens[1]

        if verb in ("freeze", "unfreeze"):
            should_be_frozen = verb == "freeze"
            if (
                name not in balances
                or (name in frozen) == should_be_frozen
            ):
                rejected.append(index)
                continue

            remember((name,))
            if should_be_frozen:
                frozen.add(name)
            else:
                frozen.remove(name)
            continue

        amount_text = tokens[-1]
        if not all("0" <= char <= "9" for char in amount_text):
            rejected.append(index)
            continue

        # Small chunks avoid Python's limit on decimal string conversion.
        amount = 0
        for start in range(0, len(amount_text), 9):
            chunk = amount_text[start:start + 9]
            amount = amount * (10 ** len(chunk)) + int(chunk)

        if verb == "open":
            if name in balances:
                rejected.append(index)
                continue

            remember((name,))
            balances[name] = amount
            continue

        if amount == 0 or name not in balances:
            rejected.append(index)
            continue

        if verb == "deposit":
            remember((name,))
            balances[name] += amount
            continue

        if name in frozen or balances[name] < amount:
            rejected.append(index)
            continue

        if verb == "withdraw":
            remember((name,))
            balances[name] -= amount
            continue

        destination = tokens[2]
        if destination == name or destination not in balances:
            rejected.append(index)
            continue

        remember((name, destination))
        balances[name] -= amount
        balances[destination] += amount

    return balances, rejected
